/** Short, individually authored introductions. Examples are conceptual unless a
 * snippet is supplied; many of these technologies require external tools. */
type Topic = {
  name: string;
  what: string;
  example: string;
  practice: string;
  code?: string;
};

type Group = { id: string; title: string; description: string; caution: string; topics: Topic[] };

